WITH flattened_attrs AS (SELECT id, host, payload_json, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs) SELECT *, STDDEV_SAMP(status_code_high) OVER w_part AS host_stddev_samp_status_code_high, AVG(status_code_high) OVER w_hist AS status_code_high_avg_2, CUME_DIST() OVER w_running AS status_code_high_cume_dist FROM flattened_attrs WINDOW w_part AS (PARTITION BY host), w_hist AS (ORDER BY status_code_high, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_running AS (PARTITION BY host ORDER BY status_code_high);
